function trasforma(input){
  var c = String(input.CondizioniPagamento).toLowerCase();
  var m = c.match(/(\d+)/), gg = m ? parseInt(m[1], 10) : 0;
  var p = input.DataFattura.split('-');
  var d = new Date(Date.UTC(+p[0], +p[1] - 1, +p[2] + gg));
  if (/f\.?\s*m\.?$|f\.m\.|fine mese/.test(c)) d = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0));
  return { scadenza: d.toISOString().slice(0, 10) };
}

