import re, calendar, datetime as dt

def trasforma(campi):
    c = str(campi['CondizioniPagamento']).lower()
    m = re.search(r'(\d+)', c)
    d = dt.date.fromisoformat(campi['DataFattura']) + dt.timedelta(days=int(m.group(1)) if m else 0)
    if 'f.m.' in c or 'fine mese' in c:
        d = d.replace(day=calendar.monthrange(d.year, d.month)[1])
    return {'scadenza': d.isoformat()}
